      "reading": "18.6650",
      "interpretation": "Preço R$17,71 ~5,12% abaixo da MM20; MM20 em queda (curto prazo de baixa)."
    },
    {
      "indicator": "MM50",
      "reading": "20.0208",
      "interpretation": "Preço ~11,54% abaixo da MM50; tendência de médio prazo negativa."
    },
    {
      "indicator": "MM200",
      "reading": "21.0265",
      "interpretation": "Preço ~15,77% abaixo da MM200; estrutura de longo prazo ainda bear."
    },
    {
      "indicator": "EMA9 e EMA21",
      "reading": "EMA9=18.0988; EMA21=18.7309",
      "interpretation": "EMA9 abaixo da EMA21 e preço abaixo de ambas → impulso vendedor de curto prazo."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD=-0.6723; signal=-0.6213; hist=-0.0510",
      "interpretation": "MACD abaixo da linha de sinal; histograma negativo (ligeira melhora recente) — momentum vendedor, sem sinal de reversão confirmado."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "BB_lower=17.3090; BB_mid=18.6650; BB_upper=20.0210",
      "interpretation": "Preço próximo à banda inferior (a R$0,401 dela, ~14,8% da largura) → pressão vendedora e possibilidade de bounce técnico."
    },
    {
      "indicator": "RSI14",
      "reading": "27.0244",
      "interpretation": "RSI < 30 (sobrevenda) — provável aumento da probabilidade de pullback de curto prazo, mas não confirma reversão de tendência."
    },
    {
      "indicator": "Volume",
      "reading": "Volume=6.083.258.000; média20d≈3.960.957.840",
      "interpretation": "Volume ~1,54× a média 20 dias; queda com volume acima da média confirma pressão vendedora e aumenta convicção do viés de baixa."
    }
  ]
}
